<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import { Truck, Store, BadgeCheck, Camera, Cpu, BatteryCharging, Smartphone, Heart, ImageOff } from 'lucide-vue-next'
import {useCatalogStore} from '../stores/catalog.js'
import {useCartStore} from '../stores/cart.js'
import {useFavoritesStore} from '../stores/favorites.js'
import {price,memoryOf,displayProductName,displayColor,displayMemory,displayCharacteristic,displayCharacteristicUnit} from '../utils/catalog.js'
import ProductCard from '../components/product/ProductCard.vue'
import LoadState from '../components/ui/LoadState.vue'
const route=useRoute(),catalog=useCatalogStore(),cart=useCartStore(),favorites=useFavoritesStore()
const product=ref(null),loading=ref(false),error=ref(''),currentImage=ref(0);let token=0
async function load(){const id=++token;loading.value=true;error.value='';currentImage.value=0;try{const result=await catalog.fetchOne(route.params.id);if(id===token)product.value=result}catch(e){if(id===token)error.value=e.message}finally{if(id===token)loading.value=false}}
watch(()=>route.params.id,load,{immediate:true})
const related=computed(()=>catalog.products.filter(p=>p.id!==product.value?.id).slice(0,4))
const selectedImage=computed(()=>product.value?.images[currentImage.value]||product.value?.images[0])
const detailItems=computed(()=>product.value?.characteristics||[])
const spec=name=>detailItems.value.find(c=>c.characteristic.toLowerCase().includes(name.toLowerCase()))?.value||'—'
</script>
<template><div class="details-page"><LoadState v-if="loading||error" :loading="loading" :error="error" @retry="load"/><template v-else-if="product"><section class="container detail-top"><div class="detail-gallery"><div class="thumbnail-list"><button v-for="(im,i) in product.images" :key="i" type="button" :class="{active:currentImage===i}" @click="currentImage=i"><img :src="im" :alt="`Photo ${i+1}`"/></button></div><div class="detail-image"><img v-if="selectedImage" :src="selectedImage" :alt="product.name"/><ImageOff v-else :size="64"/></div></div><div class="detail-info"><h1>{{ displayProductName(product) }}</h1><div class="detail-price"><strong>{{ price(product.salePrice) }}</strong><del v-if="product.salePrice<product.price">{{ price(product.price) }}</del></div><div class="detail-feature-grid"><div><Smartphone :size="22"/><span>Screen size <b>{{ spec('Диагональ') }}”</b></span></div><div><Cpu :size="22"/><span>CPU <b>{{ spec('Процессор') }}</b></span></div><div><Cpu :size="22"/><span>Memory <b>{{ displayMemory(product)||'—' }}</b></span></div><div><Camera :size="22"/><span>Camera <b>—</b></span></div><div><Camera :size="22"/><span>Resolution <b>{{ spec('Разрешение') }}</b></span></div><div><BatteryCharging :size="22"/><span>Battery <b>{{ spec('Аккумулятор') }} mAh</b></span></div></div><p class="detail-description">Enhanced capabilities thanks to an enlarged display and improved performance. Incredible photos and powerful features to enjoy every day.</p><div class="detail-actions"><button type="button" class="outline-button" @click="favorites.toggle(product.id)">{{ favorites.has(product.id)?'Remove from Wishlist':'Add to Wishlist' }}</button><button type="button" class="buy-button" :disabled="!product.available" @click="cart.add(product.id)">{{ cart.quantityOf(product.id)?'Add Another to Cart':'Add to Cart' }}</button></div><div class="detail-perks"><div><Truck :size="29"/><span>Free Delivery <b>1-2 day</b></span></div><div><Store :size="29"/><span>In Stock <b>{{ product.available?'Today':'Unavailable' }}</b></span></div><div><BadgeCheck :size="29"/><span>Guaranteed <b>{{ Math.max(1,Math.round(product.guarantee/12)) }} year</b></span></div></div></div></section><section class="details-bg"><div class="container"><div class="specs-card"><h2>Details</h2><p>Just as a book is judged by its cover, the first thing you notice when you pick up a modern smartphone is the display. Nothing surprising, because advanced technologies allow you to practically level the display frames and cutouts for the front camera and speaker, leaving no room for bold design solutions. And how good that in such realities Apple everything is fine with displays. Both critics and mass consumers always praise the quality of the picture provided by the products of the Californian brand. And last year's 6.7-inch Retina panels, which had ProMotion, caused real admiration for many.</p><div class="spec-row"><span>Brand</span><span>{{ product.brand }}</span></div><div class="spec-row"><span>Color</span><span>{{ displayColor(product.color) }}</span></div><div class="spec-row" v-for="(row,index) in detailItems" :key="index"><span>{{ displayCharacteristic(row.characteristic) }}</span><span>{{ row.value }} {{ displayCharacteristicUnit(row.unit_type) }}</span></div></div></div></section><section class="container ratings-section"><div class="rating-box"><strong>{{ product.rating.toFixed(1) }}</strong><span>of {{ product.reviewCount }} reviews</span><div>★★★★★</div></div></section><section class="container related-section"><h2>Related Products</h2><div class="products-grid"><ProductCard v-for="p in related" :key="p.id" :product="p"/></div></section></template></div></template>
